/// <reference lib="webworker" />
import { clientsClaim } from 'workbox-core';
import { ExpirationPlugin } from 'workbox-expiration';
import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { StaleWhileRevalidate, NetworkFirst, CacheFirst } from 'workbox-strategies';
import { BackgroundSyncPlugin } from 'workbox-background-sync';

declare const self: ServiceWorkerGlobalScope;

clientsClaim();

// Precache all of the assets generated by your build process.
precacheAndRoute(self.__WB_MANIFEST || []);

// Cache versioning (Issue #917)
export const CACHE_VERSION = 'v1';
export const CURRENT_CACHES = {
  js: `static-js-${CACHE_VERSION}`,
  css: `static-css-${CACHE_VERSION}`,
  images: `images-${CACHE_VERSION}`,
  imagesExt: `images-ext-${CACHE_VERSION}`,
  externalImages: `external-images-${CACHE_VERSION}`,
  api: `api-responses-${CACHE_VERSION}`,
  fonts: `fonts-${CACHE_VERSION}`,
  offlineFallback: `offline-fallback-${CACHE_VERSION}`,
};

// Offline fallback page
const offlineFallbackPage = '/offline.html';

// Consolidated Navigation Route (Issues #915 & #916)
// Replaces invalid /index.html CRA binding and consolidates navigation handling into a single NetworkFirst + Offline fallback strategy.
const fileExtensionRegexp = new RegExp('/[^/?]+\\.[^/]+$');

registerRoute(
  ({ request, url }: { request: Request; url: URL }) => {
    if (request.mode !== 'navigate') return false;
    if (url.pathname.startsWith('/_')) return false;
    if (url.pathname.match(fileExtensionRegexp)) return false;
    return true;
  },
  async ({ request }) => {
    try {
      const response = await fetch(request);
      if (response && response.status === 200) {
        return response;
      }
    } catch {
      // Offline fallback handling
    }

    try {
      const cache = await caches.open(CURRENT_CACHES.offlineFallback);
      const cachedResponse = await cache.match(offlineFallbackPage);
      if (cachedResponse) return cachedResponse;

      const fallbackFetch = await fetch(offlineFallbackPage);
      if (fallbackFetch) {
        await cache.put(offlineFallbackPage, fallbackFetch.clone());
        return fallbackFetch;
      }
    } catch {
      // Fallback unpopulated
    }

    return new Response('Offline', { status: 503, statusText: 'Service Unavailable' });
  }
);

// Runtime caching for static assets with cache versioning (Issue #917)
registerRoute(
  ({ url }) => url.origin === self.location.origin && url.pathname.endsWith('.js'),
  new StaleWhileRevalidate({ cacheName: CURRENT_CACHES.js }),
);

registerRoute(
  ({ url }) => url.origin === self.location.origin && url.pathname.endsWith('.css'),
  new StaleWhileRevalidate({ cacheName: CURRENT_CACHES.css }),
);

// Runtime caching for images
registerRoute(
  ({ url }) => url.origin === self.location.origin && url.pathname.endsWith('.png'),
  new CacheFirst({
    cacheName: CURRENT_CACHES.images,
    plugins: [new ExpirationPlugin({ maxEntries: 50 })],
  }),
);

registerRoute(
  ({ url }) =>
    url.origin === self.location.origin && url.pathname.match(/\.(jpg|jpeg|svg|gif|webp)$/),
  new CacheFirst({
    cacheName: CURRENT_CACHES.imagesExt,
    plugins: [new ExpirationPlugin({ maxEntries: 100 })],
  }),
);

// External images
registerRoute(
  ({ url }) =>
    url.hostname === 'images.unsplash.com' ||
    url.hostname === 'thumbs.dreamstime.com' ||
    url.hostname === 'static.vecteezy.com',
  new StaleWhileRevalidate({
    cacheName: CURRENT_CACHES.externalImages,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 100,
        maxAgeSeconds: 30 * 24 * 60 * 60,
      }),
    ],
  }),
);

// API requests with NetworkFirst
registerRoute(
  ({ url }) => url.pathname.startsWith('/api/'),
  new NetworkFirst({
    cacheName: CURRENT_CACHES.api,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 50,
        maxAgeSeconds: 24 * 60 * 60,
      }),
    ],
  }),
);

// Font caching
registerRoute(
  ({ url }) => url.pathname.match(/\.(woff2?|ttf|otf|eot)$/),
  new CacheFirst({
    cacheName: CURRENT_CACHES.fonts,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 20,
        maxAgeSeconds: 365 * 24 * 60 * 60,
      }),
    ],
  }),
);

// Background Sync for offline actions
const bgSyncPlugin = new BackgroundSyncPlugin('teachLinkSyncQueue', {
  maxRetentionTime: 24 * 60,
});

registerRoute(
  ({ url }) => url.pathname.match(/^\/api\/lessons\/[\w-]+\/progress$/),
  new NetworkFirst({ plugins: [bgSyncPlugin] }),
  'PATCH',
);

// Handle sync events
self.addEventListener('sync', (event: SyncEvent) => {
  if (event.tag === 'teachLinkSyncQueue') {
    event.waitUntil(Promise.resolve());
  }
});

// Skip waiting and claim clients
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// Clean up stale caches on activate (Issue #917)
self.addEventListener('activate', (event) => {
  const currentCacheSet = new Set(Object.values(CURRENT_CACHES));
  event.waitUntil(
    caches
      .keys()
      .then((cacheNames) =>
        Promise.all(
          cacheNames.map((cacheName) => {
            if (!currentCacheSet.has(cacheName)) {
              return caches.delete(cacheName);
            }
            return Promise.resolve(false);
          })
        )
      )
      .then(() => clientsClaim())
  );
});
